import type { ReactNode } from "react";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";

function hashString(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return h;
}
function loginColor(login: string): string {
  return `oklch(0.68 0.12 ${hashString(login) % 360})`;
}
function Avatar({ login, size = 20 }: { login: string; size?: number }) {
  return (
    <span className="mono" style={{ width: size, height: size, borderRadius: "50%", background: loginColor(login), color: "#1a120a", fontWeight: 700, fontSize: size * 0.46, display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
      {login[0]?.toUpperCase() ?? "?"}
    </span>
  );
}
function timeAgo(iso: string): string {
  if (!iso) return "";
  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
  if (!isFinite(s) || s < 0) return "";
  if (s < 60) return `${s}s ago`;
  const m = Math.floor(s / 60); if (m < 60) return `${m}m ago`;
  const hr = Math.floor(m / 60); if (hr < 24) return `${hr}h ago`;
  const d = Math.floor(hr / 24); return `${d}d ago`;
}

export interface ActivityItem {
  login: string;
  action: string;
  target: string;
  repo: string;
  createdAt: string;
}
const DEMO_ITEMS: ActivityItem[] = [
  { login: "octocat", action: "merged", target: "#412 live fleet roster", repo: "acme/api", createdAt: new Date(Date.now() - 3600000).toISOString() },
  { login: "hubot", action: "pushed", target: "abc123 wip", repo: "acme/web", createdAt: new Date(Date.now() - 7200000).toISOString() },
];
const DEMO_TONE: Record<string, string> = { merged: "var(--success)", pushed: "var(--info)" };
export function ActivityFeed({ items = DEMO_ITEMS, hint = "across all repos", loading = false, tone = DEMO_TONE, right, actionWidth = 80 }: {
  items?: ActivityItem[];
  hint?: string;
  loading?: boolean;
  tone?: Record<string, string>;
  right?: ReactNode;
  actionWidth?: number;
}) {
  return (
    <div className="card" style={{ padding: "14px 16px" }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 10 }}>
        <h3 style={{ margin: 0 }}>Recent activity</h3>
        <span className="hint">{hint}</span>
        {right != null && <><div style={{ flex: 1 }} />{right}</>}
      </div>
      {loading && items.length === 0 && (
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} h={40} radius={6} />)}
        </div>
      )}
      {!loading && items.length === 0 && (
        <EmptyState size="sm" title="No recent activity"
          description="Recent events across your repos surface here." />
      )}
      {items.length > 0 && (
        <div style={{ display: "flex", flexDirection: "column", gap: 1, borderRadius: 6, border: "1px solid var(--border-soft)", overflow: "hidden" }}>
          {items.map((e, i) => (
            <div key={i} style={{
              padding: "10px 12px",
              background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)",
              display: "grid", gridTemplateColumns: `22px ${actionWidth}px 1fr 110px 50px`,
              gap: 10, alignItems: "center", fontSize: 11,
            }}>
              <Avatar login={e.login} />
              <span className="mono" style={{ fontSize: 10.5, color: tone[e.action] ?? "var(--fg-muted)" }}>{e.action}</span>
              <span style={{ color: "var(--fg)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{e.target}</span>
              <span className="mono" style={{ fontSize: 10, color: "var(--fg-dim)" }}>{e.repo}</span>
              <span className="mono" style={{ fontSize: 10, color: "var(--fg-dim)", textAlign: "right" }}>{timeAgo(e.createdAt)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

